"""Generate research/RANKINGS_FINAL.md from the final top-10 CSVs (no hand-typed numbers)."""
from __future__ import annotations

import pandas as pd

from src.config import REPORTS_DIR, RESEARCH_DIR

MO = REPORTS_DIR / "model_outputs"


def _f(x, fmt):
    return "–" if pd.isna(x) else format(x, fmt)


def build() -> str:
    L = ["# Final Rankings: Most Reliable Under Pressure, Players RR Can Sign (auto-generated)", "",
         "> **Status: FINAL (information cut-off 14 Nov 2026).** Generated by `src/reporting/rankings_doc.py` from "
         "`reports/top_10_batsmen.csv`, `reports/top_10_bowlers.csv` and `reports/model_outputs/reliability_{batting,bowling}.csv`.",
         "> Supersedes `RANKINGS_PROVISIONAL.md`, which ranked all eligible players regardless of contract status.", "",
         "## Selection rule", "",
         "The submitted lists contain only players Rajasthan Royals can acquire at the IPL 2027 auction (`src/scouting/final_selection.py`):", "",
         "- **Not on any IPL 2026 squad** (all 10 teams, RR included), from the data-pack squad mapping.",
         "- **Not Pakistani:** no Pakistan player has appeared in the IPL since 2009 (source S13).",
         "- **Not Bangladeshi:** availability is not reliable after the BCCI-directed release of Mustafizur Rahman (S12). This is a judgement, because no formal rule was published.",
         "- **Not retired or banned from the IPL:** Andre Russell (S7), Ravichandran Ashwin (S15), Mohit Sharma (S16); Harry Brook, because it is unclear whether his ban covers 2027 (S14).", "",
         "Eligibility thresholds, scoring and weights are unchanged. **Score** is the percentile composite among *all* eligible players, so it compares "
         "directly with contracted players. **#**, P(top 10), the bootstrap interval and the range across pressure definitions are recomputed "
         "**within the acquirable pool** from the saved bootstrap and definition-variant ranks. **Overall #** is the rank among all eligible players.", ""]
    for side, f in (("batting", "top_10_batsmen.csv"), ("bowling", "top_10_bowlers.csv")):
        t = pd.read_csv(REPORTS_DIR / f)
        full = pd.read_csv(MO / f"reliability_{side}.csv")
        L += [f"## Top 10 {'batters' if side == 'batting' else 'bowlers'} RR can sign", ""]
        if side == "batting":
            L += ["| # | Overall # | Player | Country | Role | Score | HIGH balls | SR HIGH / LOW | Value /100 HIGH | IPL share of balls | P(top 10) | Bootstrap 90% rank | Range across defs |",
                  "|---:|---:|---|---|---|---:|---:|---|---:|---:|---:|---|---|"]
            L += [f"| {int(r['rank'])} | {int(r.overall_rank)} | {r.player} | {r.national_side} | {r.role} | {r.score:.0f} | {int(r.balls_high)} | "
                  f"{_f(r.sr_high, '.0f')} / {_f(r.sr_low, '.0f')} | {r.value_per100_high:+.1f} | {r.pct_balls_IPL:.0f}% | {r.p_top10:.2f} | "
                  f"{r.boot_rank_p05:.0f}–{r.boot_rank_p95:.0f} | {int(r.rank_min_across_defs)}–{int(r.rank_max_across_defs)} |" for _, r in t.iterrows()]
        else:
            L += ["| # | Overall # | Player | Country | Role | Score | HIGH legal balls | Econ HIGH / LOW | Wkts HIGH | IPL share of balls | P(top 10) | Bootstrap 90% rank | Range across defs |",
                  "|---:|---:|---|---|---|---:|---:|---|---:|---:|---:|---|---|"]
            L += [f"| {int(r['rank'])} | {int(r.overall_rank)} | {r.player} | {r.national_side} | {r.role} | {r.score:.0f} | {int(r.legal_balls_high)} | "
                  f"{_f(r.economy_high, '.2f')} / {_f(r.economy_low, '.2f')} | {int(r.wickets_high)} | {r.pct_balls_IPL:.0f}% | {r.p_top10:.2f} | "
                  f"{r.boot_rank_p05:.0f}–{r.boot_rank_p95:.0f} | {int(r.rank_min_across_defs)}–{int(r.rank_max_across_defs)} |" for _, r in t.iterrows()]
        nxt = full[full.rr_acquirable & (full["rank"] > 10)].sort_values("rank")
        L += ["", "Next acquirable: " + (", ".join(f"{r.player} ({r.score:.0f})" for _, r in nxt.iterrows()) or "none") + ".", ""]
        un = full.sort_values("overall_rank").head(10)
        L += ["Unrestricted top 10 (context only, not signable today):", "",
              "| Overall # | Player | Score | Why not in the RR list |", "|---:|---|---:|---|"]
        L += [f"| {int(r.overall_rank)} | {r.player} | {r.score:.0f} | {r.not_acquirable_reason if isinstance(r.not_acquirable_reason, str) else 'Acquirable'} |"
              for _, r in un.iterrows()]
        L.append("")
    L += ["## Caveats", "",
          "- The acquirable pool is clearly weaker than the contracted elite, and every player in it is overseas (RR can hold at most 8 overseas players).",
          "- Several players have little or no IPL record in the data. Their ratings rest on opponent-adjusted T20Is (see the IPL-share column).",
          "- The data pack has no Indian domestic cricket. Uncapped Indian freshers are rated separately from public Syed Mushtaq Ali Trophy data: see `reports/top_5_uncapped_batters.csv` and `reports/top_5_uncapped_bowlers.csv`.",
          "- Bowlers #9 and #10 are statistically indistinguishable from the next two (see `near_misses.csv`).",
          "- Players released at the 17 Nov 2026 retention deadline join the pool. Re-run `python -m src.scouting.final_selection` and the reporting steps after it.", ""]
    return "\n".join(L)


if __name__ == "__main__":
    (RESEARCH_DIR / "RANKINGS_FINAL.md").write_text(build(), encoding="utf-8")
    print("written research/RANKINGS_FINAL.md")
